program.compute:
options = read('/input/options')
ids = [x['id'] for x in options]
result = []
for k in range(goal['min_count'], min(goal['max_count'], len(ids)) + 1):
    for combo in combinations(ids, k):
        candidate = list(combo)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

program.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')

